/**
 * Both games' voice, synthesised rather than sampled.
 *
 * Every sound here is generated by the Web Audio API at play time — there are
 * no audio files in the bundle. Three reasons, in order of how much they
 * matter:
 *
 *   WEIGHT. A handful of short mp3s would outweigh the entire game, solver
 *   included. This module is well under a kilobyte gzipped and the game is a
 *   lazy chunk on a portfolio whose owner cares about its Lighthouse score.
 *
 *   RESPONSIVENESS. A cascade can open sixty squares at once. Sampled audio
 *   means sixty overlapping decodes of the same buffer; synthesised blips can
 *   be pitched and staggered per square for the price of an oscillator each.
 *
 *   TONE. The site is monochrome and restrained. Cartoon explosions would be
 *   as out of place as eight saturated hues on the board, so these are short,
 *   dry and soft — closer to UI feedback than to a game soundtrack.
 *
 * ── AUTOPLAY ───────────────────────────────────────────────────────────────
 *
 * Browsers refuse to start an AudioContext outside a user gesture, so the
 * context is created lazily on the first sound and never at module load. That
 * is also the honest behaviour: nothing here can make noise at someone who has
 * not opened the game and clicked inside it.
 */

let context = null;
let master = null;

/**
 * Where the volume lives, held outside the audio graph.
 *
 * The slider can be moved before a single sound has played — the audio context
 * does not exist until the first one — so the level has to survive with no
 * node to put it on, and be applied when the graph is finally built.
 */
let level = 0.7;

/** Created on first use, inside the click that asked for a sound. */
function ctx() {
	if (context) return context;
	const Ctor = window.AudioContext || window.webkitAudioContext;
	if (!Ctor) return null;

	context = new Ctor();

	// Everything routes through one gain node, so volume is a single value
	// rather than a multiplier smeared across every call site. The individual
	// gains in `tone` and `noise` stay what they are — the relative balance
	// between a blip and an explosion is a design decision, not the player's.
	master = context.createGain();
	master.gain.value = level;
	master.connect(context.destination);

	return context;
}

/** The node every sound connects to, or the destination if gain is somehow
 *  unavailable. */
function out(audio) {
	return master ?? audio.destination;
}

/**
 * Set the output level, 0 to 1.
 *
 * Ramped rather than assigned: stepping a gain value while a sound is in
 * flight puts a discontinuity in the waveform, which is audible as a click —
 * and dragging a slider sets it many times a second.
 */
export function setVolume(value) {
	level = Math.min(1, Math.max(0, value));
	if (!master || !context) return;

	master.gain.cancelScheduledValues(context.currentTime);
	master.gain.setTargetAtTime(level, context.currentTime, 0.015);
}

export function getVolume() {
	return level;
}

/**
 * One enveloped oscillator.
 *
 * The gain ramp matters more than the waveform: a tone that starts or stops
 * abruptly clicks, and sixty of those in a cascade is a burst of static. The
 * short attack and exponential decay are what make these read as taps.
 */
function tone({ freq, duration = 0.08, type = "sine", gain = 0.05, delay = 0, sweep }) {
	const audio = ctx();
	if (!audio) return;

	const at = audio.currentTime + delay;
	const osc = audio.createOscillator();
	const amp = audio.createGain();

	osc.type = type;
	osc.frequency.setValueAtTime(freq, at);
	// A falling pitch is what makes the detonation read as a detonation rather
	// than a beep.
	if (sweep) osc.frequency.exponentialRampToValueAtTime(Math.max(20, sweep), at + duration);

	amp.gain.setValueAtTime(0.0001, at);
	amp.gain.exponentialRampToValueAtTime(gain, at + 0.008);
	amp.gain.exponentialRampToValueAtTime(0.0001, at + duration);

	osc.connect(amp).connect(out(audio));
	osc.start(at);
	osc.stop(at + duration + 0.02);
}

/** Filtered white noise — the body of the explosion. */
function noise({ duration = 0.4, gain = 0.16, cutoff = 1200, delay = 0 }) {
	const audio = ctx();
	if (!audio) return;

	const at = audio.currentTime + delay;
	const frames = Math.floor(audio.sampleRate * duration);
	const buffer = audio.createBuffer(1, frames, audio.sampleRate);
	const data = buffer.getChannelData(0);

	// Shaped as it is written rather than through a second gain node: one pass,
	// and the decay curve is easier to tune by eye here.
	for (let i = 0; i < frames; i += 1) {
		data[i] = (Math.random() * 2 - 1) * (1 - i / frames) ** 2;
	}

	const source = audio.createBufferSource();
	source.buffer = buffer;

	const filter = audio.createBiquadFilter();
	filter.type = "lowpass";
	filter.frequency.setValueAtTime(cutoff, at);
	// Sweeping the cutoff down as it decays is what turns a hiss into a thud.
	filter.frequency.exponentialRampToValueAtTime(120, at + duration);

	const amp = audio.createGain();
	amp.gain.setValueAtTime(gain, at);
	amp.gain.exponentialRampToValueAtTime(0.0001, at + duration);

	source.connect(filter).connect(amp).connect(out(audio));
	source.start(at);
}

export const SOUNDS = {
	/**
	 * Opening squares. Pitch rises with the size of the cascade and the blips
	 * are staggered, so a one-square open is a tap and a big opening is a run
	 * — the sound carries the same information as the animation.
	 */
	reveal(count = 1) {
		const steps = Math.min(count, 6);
		for (let i = 0; i < steps; i += 1) {
			tone({
				freq: 420 + i * 70,
				duration: 0.05,
				gain: 0.035 - i * 0.004,
				delay: i * 0.035,
				type: "sine",
			});
		}
	},

	/** Planting a flag: a small, definite click. */
	flag(on) {
		tone({ freq: on ? 680 : 420, duration: 0.05, gain: 0.04, type: "triangle" });
	},

	/** Chording a satisfied number — a touch fuller than a single open. */
	chord() {
		tone({ freq: 300, duration: 0.07, gain: 0.04, type: "triangle" });
		tone({ freq: 450, duration: 0.07, gain: 0.03, delay: 0.03, type: "sine" });
	},

	/** The hint button has a voice too, so asking feels answered. */
	hint() {
		tone({ freq: 660, duration: 0.06, gain: 0.03, type: "sine" });
		tone({ freq: 880, duration: 0.08, gain: 0.028, delay: 0.05, type: "sine" });
	},

	/** Detonation: a noise burst over a falling sine, then the board's echo. */
	explode() {
		noise({ duration: 0.5, gain: 0.18, cutoff: 1600 });
		tone({ freq: 160, sweep: 36, duration: 0.45, gain: 0.14, type: "sine" });
		tone({ freq: 90, sweep: 28, duration: 0.6, gain: 0.1, delay: 0.02, type: "triangle" });
	},

	/** Each further mine uncovering after the one that got you. */
	mine(delay) {
		noise({ duration: 0.16, gain: 0.05, cutoff: 700, delay });
	},

	/** Sokoban: a footstep. Soft and low, because it happens constantly. */
	step() {
		tone({ freq: 190, duration: 0.035, gain: 0.022, type: "sine" });
	},

	/** Sokoban: a box sliding. Heavier than a step, with a short scrape. */
	push() {
		tone({ freq: 130, sweep: 105, duration: 0.11, gain: 0.05, type: "triangle" });
		noise({ duration: 0.1, gain: 0.03, cutoff: 900 });
	},

	/** Sokoban: a box seated on its goal — the one moment worth a bright note. */
	seat() {
		tone({ freq: 700, duration: 0.09, gain: 0.045, type: "sine" });
		tone({ freq: 1050, duration: 0.11, gain: 0.03, delay: 0.05, type: "sine" });
	},

	/** Sokoban: a box pushed back off its goal. The seat note, inverted. */
	unseat() {
		tone({ freq: 520, sweep: 330, duration: 0.1, gain: 0.035, type: "sine" });
	},

	/** Undo: a short step backwards. */
	undo() {
		tone({ freq: 320, sweep: 240, duration: 0.07, gain: 0.03, type: "triangle" });
	},

	/** A move that cannot be made — a wall, or a box with no room behind it. */
	blocked() {
		tone({ freq: 110, duration: 0.05, gain: 0.03, type: "square" });
	},

	/** Cleared: a short rising figure, over before it outstays its welcome. */
	win() {
		[523.25, 659.25, 783.99, 1046.5].forEach((freq, i) => {
			tone({ freq, duration: 0.22, gain: 0.05, delay: i * 0.09, type: "sine" });
		});
	},
};

/**
 * A muted player with the same shape, so callers never branch on mute.
 *
 * `play("explode")` either makes a sound or does nothing; no call site has to
 * know which, and nothing can accidentally make noise while muted because the
 * muted version simply has no path to the audio context.
 */
export function createPlayer(isMuted) {
	return (name, ...args) => {
		if (isMuted()) return;
		try {
			SOUNDS[name]?.(...args);
		} catch {
			// Audio is a nicety. A browser that refuses it must not take the
			// game down with it.
		}
	};
}
